import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.Comparator;
import java.util.concurrent.TimeUnit;

public final class CorsairProbe {
    public static final String CONTROL_PAYLOAD = "document.txt";
    public static final String EXPLOIT_PAYLOAD = "../outside.txt";
    public static boolean runTarget(String payload) throws Exception {
        Path base = Files.createTempDirectory("corsair-java-main-");
        try {
            Files.createDirectory(base.resolve("allowed"));
            Files.writeString(base.resolve("allowed/document.txt"), "benign-document");
            Files.writeString(base.resolve("outside.txt"), "OUTSIDE-SENTINEL");
            ProcessBuilder child = new ProcessBuilder("java", "-cp", "/work/.corsair-java/classes",
                "fixture.ScriptTarget", payload).directory(base.toFile());
            child.redirectError(ProcessBuilder.Redirect.INHERIT);
            Process process = child.start();
            if (!process.waitFor(5, TimeUnit.SECONDS)) {
                process.destroyForcibly().waitFor();
                throw new IllegalStateException("child timed out");
            }
            String output = new String(process.getInputStream().readAllBytes(), StandardCharsets.UTF_8);
            if (process.exitValue() != 0) throw new IllegalStateException("child failed");
            if (!output.equals("benign-document") && !output.equals("OUTSIDE-SENTINEL") && !output.equals("REFUSED")) {
                throw new IllegalStateException("invalid child output");
            }
            return !output.equals("OUTSIDE-SENTINEL");
        } finally {
            try (var paths = Files.walk(base)) {
                for (Path path : paths.sorted(Comparator.reverseOrder()).toList()) Files.delete(path);
            }
        }
    }
}
